# Seal the manifest command's outputs. Do not edit this file after it runs.
# Usage: python -I work/scripts/seal_manifest_t6v1.py NN
import hashlib
import json
import re
import sys
from pathlib import Path

if len(sys.argv) != 2 or not re.fullmatch(r'\d+', sys.argv[1]):
    sys.stderr.write('usage: python -I work/scripts/seal_manifest_t6v1.py NN\n')
    sys.exit(2)
TARGET = f'{int(sys.argv[1]):02d}'


def sha_file(path):
    data = Path(path).read_bytes()
    return hashlib.sha256(data).hexdigest(), len(data)


files = {}
for suffix in ('cmd.txt', 'out', 'err', 'exit'):
    path = Path(f'work/out/cmd/{TARGET}.{suffix}')
    if not path.is_file():
        sys.stderr.write('missing ' + str(path) + '\n')
        sys.exit(2)
    digest, nbytes = sha_file(path)
    files[suffix] = {'path': f'work/out/cmd/{TARGET}.{suffix}', 'sha256': digest, 'bytes': nbytes}

manifest_sha, manifest_bytes = sha_file('work/evidence-manifest.json')
supplement_sha, supplement_bytes = sha_file('work/out/manifest-supplement-t6v1.json')
doc = {
    'seals_command': TARGET,
    'files': files,
    'evidence_manifest': {
        'path': 'work/evidence-manifest.json',
        'sha256': manifest_sha,
        'bytes': manifest_bytes,
    },
    'preliminary_supplement': {
        'path': 'work/out/manifest-supplement-t6v1.json',
        'sha256': supplement_sha,
        'bytes': supplement_bytes,
    },
    'note': (
        'This process hashes the manifest command. It cannot hash its own '
        'work/out/cmd wrapper .out, .err or .exit. The wrapper writes those files '
        'after this process returns, and the .exit file contains a timestamp.'
    ),
}
Path('work/out/manifest-seal-t6v1.json').write_text(json.dumps(doc, indent=2) + '\n', encoding='utf-8')
print('sealed', TARGET, files['exit']['sha256'])
